class User:
    def __init__(self, uid, name):
        self.uid, self.name = uid, name
    def __eq__(self, other):
        return isinstance(other, User) and self.uid == other.uid and self.name == other.name
    def __repr__(self):
        return f'User({self.uid})'

repo = MemoryRepository(key_fn=lambda u: str(u.uid))
seed(repo, [User(1, 'a'), User(2, 'b')])
assert repo.get('1') == User(1, 'a')
assert repo.get('99') is None
assert len(repo.all()) == 2
print('ok')
